from boltons.jsonutils import JSONLIterator
import io

def test_rel_seek_1():
    content = '{"1": 1}\n{"2": 2}\n'
    f = io.StringIO(content)
    try:
        JSONLIterator(f, rel_seek=1.0)
        print("rel_seek=1.0 accepted")
    except ValueError as e:
        print(f"rel_seek=1.0 rejected: {e}")

def test_rel_seek_minus_1():
    content = '{"1": 1}\n{"2": 2}\n'
    f = io.StringIO(content)
    try:
        JSONLIterator(f, rel_seek=-1.0)
        print("rel_seek=-1.0 accepted")
    except ValueError as e:
        print(f"rel_seek=-1.0 rejected: {e}")

if __name__ == '__main__':
    test_rel_seek_1()
    test_rel_seek_minus_1()
